scripts.script:
getgenv().score = 0x7FFFFFFFFFFFFDFF -- Whatever score you want, highest number I could get it to without wrapping back is default.

local mt = getrawmetatable(game)
setreadonly(mt, false)

local nc = mt.__namecall
mt.__namecall = newcclosure(function(self, ...)
	local args = {...}

	if getnamecallmethod() == "FireServer" and self.Name == "UpdateScore" then
		args[1] = getgenv().score
		return nc(self, unpack(args))
	end

	return nc(self, ...)
end)

local args = {
    [1] = -1000000000000000000, -- here the ammount dont delte the minus
    [2] = -10
}

game:GetService("ReplicatedStorage").GameValues.SendItem:FireServer(unpack(args))

_G.autoCoins = true;
 while _G.autoCoins == true do
local args = {
    [1] = "Bread",
    [2] = 17237895
}
game:GetService("ReplicatedStorage").IBS_Recovery:FireServer(unpack(args))
wait()
 end

while true do task.wait()
    game:GetService("Workspace")[game.Players.LocalPlayer.Name.."-PlotClient"].top.Size = Vector3.new(300,.1,300)
end
